import{_ as s,o as e,c as t,a3 as i}from"./chunks/framework.BMJIGmOB.js";const g=JSON.parse('{"title":"开发工具","description":"Git 与 Maven 的常用命令和工程实践。","frontmatter":{"title":"开发工具","description":"Git 与 Maven 的常用命令和工程实践。","date":"2026-11-20T00:00:00.000Z","category":"匠心造物","subCategory":"Java 面试","tags":["面试","Git","Maven"],"author":"闲生"},"headers":[],"relativePath":"posts/create/interview/dev-tools.md","filePath":"posts/create/interview/dev-tools.md"}'),n={name:"posts/create/interview/dev-tools.md"};function l(p,a,o,c,d,r){return e(),t("div",null,[...a[0]||(a[0]=[i(`<h1 id="开发工具" tabindex="-1">开发工具 <a class="header-anchor" href="#开发工具" aria-label="Permalink to &quot;开发工具&quot;">​</a></h1><blockquote><p>开发工具问题汇总。</p></blockquote><h2 id="git" tabindex="-1">Git <a class="header-anchor" href="#git" aria-label="Permalink to &quot;Git&quot;">​</a></h2><h3 id="git中5个区-和具体操作" tabindex="-1">Git中5个区，和具体操作？ <a class="header-anchor" href="#git中5个区-和具体操作" aria-label="Permalink to &quot;Git中5个区，和具体操作？&quot;">​</a></h3><ul><li>代码提交和同步代码</li></ul><p><img src="https://cdn.jsdelivr.net/gh/jokerxian/pic/pics/16ce5217ce.png" alt=""></p><ul><li>代码撤销和撤销同步</li></ul><p><img src="https://cdn.jsdelivr.net/gh/jokerxian/pic/pics/5df4beac57.png" alt=""></p><h3 id="平时是怎么提交代码的" tabindex="-1">平时是怎么提交代码的？ <a class="header-anchor" href="#平时是怎么提交代码的" aria-label="Permalink to &quot;平时是怎么提交代码的？&quot;">​</a></h3><ul><li>第零步: 工作区与仓库保持一致</li><li>第一步: 文件增删改，变为已修改状态</li><li>第二步: git add ，变为已暂存状态</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" tabindex="0"><code><span class="line"><span>$ git status</span></span>
<span class="line"><span>$ git add --all # 当前项目下的所有更改</span></span>
<span class="line"><span>$ git add .  # 当前目录下的所有更改</span></span>
<span class="line"><span>$ git add xx/xx.py xx/xx2.py  # 添加某几个文件</span></span></code></pre></div><ul><li>第三步: git commit，变为已提交状态</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" tabindex="0"><code><span class="line"><span>$ git commit -m &quot;&lt;这里写commit的描述&gt;&quot;</span></span></code></pre></div><ul><li>第四步: git push，变为已推送状态</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" tabindex="0"><code><span class="line"><span>$ git push -u origin master # 第一次需要关联上</span></span>
<span class="line"><span>$ git push # 之后再推送就不用指明应该推送的远程分支了</span></span>
<span class="line"><span>$ git branch # 可以查看本地仓库的分支</span></span>
<span class="line"><span>$ git branch -a # 可以查看本地仓库和本地远程仓库(远程仓库的本地镜像)的所有分支</span></span></code></pre></div><p>在某个分支下，我最常用的操作如下</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" tabindex="0"><code><span class="line"><span>$ git status</span></span>
<span class="line"><span>$ git add -a</span></span>
<span class="line"><span>$ git status</span></span>
<span class="line"><span>$ git commit -m &#39;xxx&#39;</span></span>
<span class="line"><span>$ git pull --rebase</span></span>
<span class="line"><span>$ git push origin xxbranch</span></span></code></pre></div><h2 id="maven" tabindex="-1">Maven <a class="header-anchor" href="#maven" aria-label="Permalink to &quot;Maven&quot;">​</a></h2><h3 id="maven中包的依赖原则-如何解决冲突" tabindex="-1">Maven中包的依赖原则？如何解决冲突？ <a class="header-anchor" href="#maven中包的依赖原则-如何解决冲突" aria-label="Permalink to &quot;Maven中包的依赖原则？如何解决冲突？&quot;">​</a></h3><ul><li><strong>依赖原则</strong>？</li></ul><ol><li>依赖路径最短优先原则</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" tabindex="0"><code><span class="line"><span>A -&gt; B -&gt; C -&gt; X(1.0)</span></span>
<span class="line"><span>A -&gt; D -&gt; X(2.0)</span></span></code></pre></div><p>由于 X(2.0) 路径最短，所以使用 X(2.0)。</p><ol start="2"><li>声明顺序优先原则</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" tabindex="0"><code><span class="line"><span>A -&gt; B -&gt; X(1.0)</span></span>
<span class="line"><span>A -&gt; C -&gt; X(2.0)</span></span></code></pre></div><p>在 POM 中最先声明的优先，上面的两个依赖如果先声明 B，那么最后使用 X(1.0)。</p><ol start="3"><li>覆写优先原则</li></ol><p>子 POM 内声明的依赖优先于父 POM 中声明的依赖。</p><ul><li><strong>如何解决冲突</strong>？</li></ul><ol><li><p>找到 Maven 加载的 Jar 包版本，使用 <code>mvn dependency:tree</code> 查看依赖树，根据依赖原则来调整依赖在 POM 文件的声明顺序。</p></li><li><p>发现了冲突的包之后，剩下的就是选择一个合适版本的包留下，如果是传递依赖的包正确，那么把显示依赖的包exclude掉。如果是某一个传递依赖的包有问题，那么我们需要手动把这个传递依赖execlude掉</p></li></ol><h3 id="maven-项目生命周期与构建原理" tabindex="-1">Maven 项目生命周期与构建原理？ <a class="header-anchor" href="#maven-项目生命周期与构建原理" aria-label="Permalink to &quot;Maven 项目生命周期与构建原理？&quot;">​</a></h3><p>Maven从项目的三个不同的角度，定义了单套生命周期，三套生命周期是相互独立的，它们之间不会相互影响。</p><ul><li>默认构建生命周期(Default Lifeclyle): 该生命周期表示这项目的构建过程，定义了一个项目的构建要经过的不同的阶段。</li><li>清理生命周期(Clean Lifecycle): 该生命周期负责清理项目中的多余信息，保持项目资源和代码的整洁性。一般拿来清空directory(即一般的target)目录下的文件。</li><li>站点管理生命周期(Site Lifecycle) :向我们创建一个项目时，我们有时候需要提供一个站点，来介绍这个项目的信息，如项目介绍，项目进度状态、项目组成成员，版本控制信息，项目javadoc索引信息等等。站点管理生命周期定义了站点管理过程的各个阶段。</li></ul><p><img src="https://cdn.jsdelivr.net/gh/jokerxian/pic/pics/12ca3aa2e9.jpg" alt=""></p><hr><blockquote><p>本章整理自 <a href="https://pdai.tech/md/interview/x-interview.html" target="_blank" rel="noreferrer">pdai.tech《Java 全栈知识点问题汇总》</a>，仅作个人复习存档；图片已转存至自建图床，少数原图失效处保留了待补标记。</p></blockquote>`,36)])])}const v=s(n,[["render",l]]);export{g as __pageData,v as default};
